@startuml

class Provider {
  + Name : string
  + Location : string
}

class Cruise {
  + Number : int
  + Name : string
  + StartDate : date
  + EndDate : date
}

class Employee {
  + Name : string
  + Ssn : int
}

class Guest {
  + Name : string
  + IsVIP : boolean
}

class Ship {
  + Name : string
  + Decks : int
  + Length : float
  + PassengerCount : int
}

class TravelAgency {
  + Name : string
  + Address : string
}

class Booking {
  + BookingNumber : string
  + BookingDate : date
}

class DestinationArea {
  + Name : string
  + SeaName : string
}

class Show {
  + Title : string
  + Duration : int
}

class Ticket {
}

Provider "1" -- "*" Cruise : organizes
Cruise "*" -- "*" Employee : requires
Cruise "*" -- "*" Guest : has
Cruise "*" -- "1" Ship : uses
Cruise "*" -- "1" DestinationArea : heads for
Cruise "1" -- "*" Show : offers
Cruise "1" -- "*" Ticket : issues
TravelAgency "1" -- "*" Booking : manages
Booking "*" -- "1" Cruise : for
Guest "1" -- "*" Ticket : holds
Ticket "*" -- "1" Cruise : belongs to

@enduml

